SELECT data.commit.collection::VARCHAR AS event, count() AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT data.commit.collection::VARCHAR AS event, count() AS count, count(DISTINCT data.did::VARCHAR) AS users FROM bluesky WHERE data.kind::VARCHAR = 'commit' AND data.commit.operation::VARCHAR = 'create' GROUP BY event ORDER BY count DESC;
SELECT data.commit.collection::VARCHAR AS event, hour(TO_TIMESTAMP(data.time_us::BIGINT / 1000000)) AS hour_of_day, count() AS count FROM bluesky WHERE data.kind::VARCHAR = 'commit' AND data.commit.operation::VARCHAR = 'create' AND data.commit.collection::VARCHAR IN ['app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like'] GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT data.did::VARCHAR AS user_id, TO_TIMESTAMP(MIN(data.time_us::BIGINT) / 1000000) AS first_post_date FROM bluesky WHERE data.kind::VARCHAR = 'commit' AND data.commit.operation::VARCHAR = 'create' AND data.commit.collection::VARCHAR = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_date ASC LIMIT 3;
SELECT data.did::VARCHAR AS user_id, date_diff('milliseconds', TO_TIMESTAMP(MIN(data.time_us::BIGINT) / 1000000), TO_TIMESTAMP(MAX(data.time_us::BIGINT) / 1000000)) AS activity_span FROM bluesky WHERE data.kind::VARCHAR = 'commit' AND data.commit.operation::VARCHAR = 'create' AND data.commit.collection::VARCHAR = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
